const output = [];

for (const item of $input.all()) {
  let data = item.json;

  try {
    // If AI output is inside a string, parse it
    if (typeof data === 'string') {
      data = JSON.parse(data);
    }

    // Handle common AI output fields
    if (typeof data.output === 'string') {
      data = JSON.parse(data.output);
    }

    if (typeof data.text === 'string') {
      data = JSON.parse(data.text);
    }

    // Clean the record
    const cleaned = {
      Student_ID: String(data.Student_ID ?? '').trim(),
      Name: String(data.Name ?? '').trim(),
      Email: String(data.Email ?? '').trim().toLowerCase(),
      Phone: String(data.Phone ?? '').trim(),
      Course: String(data.Course ?? '').trim(),
      Fee_Paid: Boolean(data.Fee_Paid),
      City: String(data.City ?? '').trim(),
      Enrolled_Date: String(data.Enrolled_Date ?? '').trim(),
    };

    // Email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const emailValid = emailRegex.test(cleaned.Email);

    // Phone validation
    const phoneDigits = cleaned.Phone.replace(/\D/g, '');
    const phoneValid = /^[0-9]{10}$/.test(phoneDigits);

    // Date validation
    const dateValid = /^\d{4}-\d{2}-\d{2}$/.test(cleaned.Enrolled_Date);

    // Add validation status
    cleaned.Email = emailValid ? cleaned.Email : '';
    cleaned.Phone = phoneValid ? phoneDigits : '';

    cleaned.Email_Valid = emailValid;
    cleaned.Phone_Valid = phoneValid;
    cleaned.Date_Valid = dateValid;

    output.push({
      json: cleaned
    });

  } catch (error) {
    // Keep bad records instead of stopping the entire workflow
    output.push({
      json: {
        ...data,
        Parse_Error: true,
        Error_Message: error.message
      }
    });
  }
}

return output;
